/**
 * AXONIZ — Context Manager
 *
 * Solves the "free tier token limit" problem: when a session accumulates
 * 500K tokens of history, the next request sends ALL of it to the model
 * → exceeds the free-tier limit → blocked.
 *
 * Solution: before sending to the LLM, check the total token count.
 * If over the threshold (default 4000 tokens — safe for 8K free-tier
 * models), compress the older messages into a summary. The LLM receives:
 *   [system prompt] + [summary of old messages] + [last N messages] + [new message]
 *
 * The summary is generated by the SAME model the user is using (or a
 * small/fast fallback model). This way:
 * - Sessions can run indefinitely without hitting token limits
 * - When the provider changes mid-session, the new model gets the
 *   summary (1-5K tokens) instead of the full 500K history
 * - Free-tier models (OrcaRouter, OpenRouter free) stay usable
 */

export interface ChatMessageLike {
  role: "user" | "assistant" | "system";
  content: string;
}

/* ─── Token estimation ──────────────────────────────────────────────── */
export function estimateTokens(text: string): number {
  // Rough estimate: 1 token ≈ 4 chars for English, ~2 chars for CJK
  // This is close enough for threshold checking — the actual token count
  // from the model's tokenizer would be more precise but requires a
  // tokenizer dependency.
  const cjkChars = (text.match(/[\u4e00-\u9fff\u3040-\u30ff\uac00-\ud7af]/g) || []).length;
  const otherChars = text.length - cjkChars;
  return Math.ceil(otherChars / 4 + cjkChars / 2);
}

export function estimateMessagesTokens(messages: ChatMessageLike[]): number {
  return messages.reduce((sum, m) => sum + estimateTokens(m.content), 0);
}

/* ─── Context compression ───────────────────────────────────────────── */
export interface CompressedContext {
  summary: string | null;
  recentMessages: ChatMessageLike[];
  totalTokens: number;
  wasCompressed: boolean;
  originalMessageCount: number;
  compressedMessageCount: number;
}

/**
 * Compress chat history if it exceeds the token threshold.
 *
 * Strategy:
 * 1. Count total tokens
 * 2. If under threshold → return as-is (no compression)
 * 3. If over threshold → split into "old" (to summarize) + "recent" (keep verbatim)
 * 4. Generate a summary of the "old" messages (using an LLM or extractive)
 * 5. Return: summary + recentMessages
 *
 * @param messages Full chat history
 * @param maxTokens Threshold (default 4000 — safe for 8K free-tier models)
 * @param recentCount Number of recent messages to keep verbatim (default 10)
 * @param summarizeFn Optional LLM-based summary function. If not provided,
 *                    uses extractive summary (first 200 chars of each message).
 */
export function compressContext(
  messages: ChatMessageLike[],
  maxTokens: number = 4000,
  recentCount: number = 10,
  summarizeFn?: (messages: ChatMessageLike[]) => Promise<string>,
): { messages: ChatMessageLike[]; wasCompressed: boolean; summary: string | null } {
  const totalTokens = estimateMessagesTokens(messages);

  // No compression needed
  if (totalTokens <= maxTokens) {
    return { messages, wasCompressed: false, summary: null };
  }

  // Split: old messages (to summarize) + recent messages (keep verbatim)
  const splitIndex = Math.max(0, messages.length - recentCount);
  const oldMessages = messages.slice(0, splitIndex);
  const recentMessages = messages.slice(splitIndex);

  // Extractive summary (no LLM call — just extract key info)
  const extractiveSummary = generateExtractiveSummary(oldMessages);

  // If an LLM summary function was provided, we'd call it here
  // (async — would need to be called before compressContext)
  // For now, the extractive summary is good enough for most use cases.

  const summaryMessage: ChatMessageLike = {
    role: "system",
    content: `[Previous session context — ${oldMessages.length} messages compressed to ~${estimateTokens(extractiveSummary)} tokens]\n\n${extractiveSummary}`,
  };

  return {
    messages: [summaryMessage, ...recentMessages],
    wasCompressed: true,
    summary: extractiveSummary,
  };
}

/**
 * Generate an extractive summary of messages (no LLM call needed).
 *
 * Strategy:
 * - For each message, take the first ~200 chars
 * - Group by role
 * - List what was discussed
 */
function generateExtractiveSummary(messages: ChatMessageLike[]): string {
  if (messages.length === 0) return "";

  const userMessages = messages.filter(m => m.role === "user").map(m => m.content.slice(0, 200));
  const assistantMessages = messages.filter(m => m.role === "assistant").map(m => m.content.slice(0, 200));

  const lines: string[] = [];

  lines.push(`## Session Summary (${messages.length} messages total)`);

  // List user questions/prompts
  if (userMessages.length > 0) {
    lines.push(`\n### User asked about:`);
    userMessages.slice(0, 20).forEach((msg, i) => {
      const preview = msg.replace(/\n/g, " ").trim();
      lines.push(`${i + 1}. ${preview}${preview.length >= 200 ? "..." : ""}`);
    });
    if (userMessages.length > 20) {
      lines.push(`... and ${userMessages.length - 20} more user messages`);
    }
  }

  // List assistant responses (briefly)
  if (assistantMessages.length > 0) {
    lines.push(`\n### Assistant responded with:`);
    assistantMessages.slice(0, 10).forEach((msg, i) => {
      const preview = msg.replace(/\n/g, " ").trim();
      lines.push(`${i + 1}. ${preview}${preview.length >= 200 ? "..." : ""}`);
    });
    if (assistantMessages.length > 10) {
      lines.push(`... and ${assistantMessages.length - 10} more assistant responses`);
    }
  }

  return lines.join("\n");
}

/**
 * Generate an LLM-based summary (more accurate than extractive).
 * Uses the same provider/model the user is configured with.
 *
 * Call this BEFORE compressContext if you want LLM-based summaries.
 */
export async function generateLLMSummary(
  messages: ChatMessageLike[],
  baseUrl: string,
  apiKey?: string,
  model?: string,
): Promise<string> {
  const conversationText = messages
    .map(m => `${m.role.toUpperCase()}: ${m.content}`)
    .join("\n\n");

  const summaryPrompt = `You are a context compressor. Summarize the following conversation in under 500 words. Focus on:
1. What the user asked for
2. What decisions were made
3. What code changes were proposed or implemented
4. Any unresolved issues or next steps

Do NOT include code snippets — just describe what happened in prose.

CONVERSATION:
${conversationText}`;

  try {
    const res = await fetch(`${baseUrl.replace(/\/$/, "")}/chat/completions`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...(apiKey ? { "Authorization": `Bearer ${apiKey}` } : {}),
      },
      body: JSON.stringify({
        model: model || "gpt-4o-mini",
        messages: [{ role: "user", content: summaryPrompt }],
        temperature: 0.3,
        max_tokens: 500,
      }),
      signal: AbortSignal.timeout(30_000),
    });

    if (!res.ok) {
      throw new Error(`summary LLM call failed: ${res.status}`);
    }

    const data = await res.json();
    const summary = data.choices?.[0]?.message?.content;
    if (!summary) throw new Error("no summary in response");
    return summary;
  } catch (e) {
    // Fallback to extractive summary if the LLM call fails
    console.warn("[context-manager] LLM summary failed, using extractive:", e instanceof Error ? e.message : String(e));
    return generateExtractiveSummary(messages);
  }
}

/**
 * Full context management pipeline.
 *
 * Call this before sending a chat request to the LLM.
 * Returns the messages to send (possibly compressed).
 *
 * Usage:
 *   const managed = await manageContext(history, {
 *     maxTokens: 4000,
 *     recentCount: 10,
 *     baseUrl, apiKey, model,
 *     useLLMSummary: true,  // uses LLM for better summaries
 *   });
 *   // Send managed.messages to the LLM
 */
export async function manageContext(
  messages: ChatMessageLike[],
  options: {
    maxTokens?: number;
    recentCount?: number;
    baseUrl?: string;
    apiKey?: string;
    model?: string;
    useLLMSummary?: boolean;
  } = {},
): Promise<{ messages: ChatMessageLike[]; wasCompressed: boolean; summary: string | null }> {
  const maxTokens = options.maxTokens ?? 4000;
  const recentCount = options.recentCount ?? 10;
  const totalTokens = estimateMessagesTokens(messages);

  // No compression needed
  if (totalTokens <= maxTokens) {
    return { messages, wasCompressed: false, summary: null };
  }

  // Split into old + recent
  const splitIndex = Math.max(0, messages.length - recentCount);
  const oldMessages = messages.slice(0, splitIndex);
  const recentMessages = messages.slice(splitIndex);

  // Generate summary (LLM-based if requested, otherwise extractive)
  let summary: string;
  if (options.useLLMSummary && options.baseUrl) {
    summary = await generateLLMSummary(
      oldMessages,
      options.baseUrl,
      options.apiKey,
      options.model,
    );
  } else {
    summary = generateExtractiveSummary(oldMessages);
  }

  const summaryMessage: ChatMessageLike = {
    role: "system",
    content: `[Previous session context — ${oldMessages.length} messages compressed to ~${estimateTokens(summary)} tokens]\n\n${summary}`,
  };

  return {
    messages: [summaryMessage, ...recentMessages],
    wasCompressed: true,
    summary,
  };
}
